'use client';

import type { HTMLAttributes, ReactNode } from 'react';
import { useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { RiSparklingFill } from '@remixicon/react';
import { Button } from '@/components/base/buttons/button';
import { CloseButton } from '@/components/base/buttons/close-button';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type AnnouncementProps = Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'onDrag' | 'onDragStart' | 'onDragEnd' | 'onAnimationStart' | 'onAnimationEnd'> & {
  title: ReactNode;
  description?: ReactNode;
  icon?: IconComponent;
  actionLabel?: ReactNode;
  onAction?: () => void;
  dismissible?: boolean;
  closeLabel?: string;
  onClose?: () => void;
};

export function Announcement({
  title,
  description,
  icon: Icon = RiSparklingFill,
  actionLabel,
  onAction,
  dismissible = false,
  closeLabel = 'Dismiss announcement',
  onClose,
  className,
  ...props
}: AnnouncementProps) {
  const [open, setOpen] = useState(true);
  const reduceMotion = useReducedMotion();

  return (
    <AnimatePresence onExitComplete={onClose}>
      {open && (
        <motion.div
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, y: -5, filter: 'blur(3px)' }}
          transition={{ duration: reduceMotion ? 0.01 : 0.2, ease: 'easeOut' }}
          className={cx('ui-announcement', className)}
          {...props}
        >
          <div className="ui-announcement__top">
            <Icon className="ui-announcement__icon" aria-hidden />
            {dismissible && <CloseButton size="xs" aria-label={closeLabel} onClick={() => setOpen(false)} />}
          </div>
          <div className="ui-announcement__copy">
            <p className="ui-announcement__title">{title}</p>
            {description && <p className="ui-announcement__description">{description}</p>}
          </div>
          {actionLabel && <Button variant="secondary" size="small" className="ui-announcement__action" onClick={onAction}>{actionLabel}</Button>}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import type { HTMLAttributes } from 'react';
import { useEffect, useRef, useState } from 'react';
import { cx } from '@/utils/cx';

export type AvatarSize = 'xs' | 'sm' | 'md' | 'lg';
export type AvatarColor = 'neutral' | 'blue' | 'lime' | 'pink';

export type AvatarProps = Omit<HTMLAttributes<HTMLSpanElement>, 'color'> & {
  size?: AvatarSize;
  color?: AvatarColor;
  initials?: string;
  src?: string;
  alt?: string;
};

export function Avatar({ size = 'md', color = 'neutral', initials, src, alt, className, ...props }: AvatarProps) {
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const showImage = Boolean(src && src !== failedSource);

  useEffect(() => {
    const image = imageRef.current;
    if (!image || !src) return;
    const fail = () => setFailedSource(src);
    if (image.complete && image.naturalWidth === 0) fail();
    image.addEventListener('error', fail);
    return () => image.removeEventListener('error', fail);
  }, [src, showImage]);

  return (
    <span role="img" aria-label={alt || initials || 'Avatar'} data-size={size} data-color={color} className={cx('ui-avatar', className)} {...props}>
      <span className="ui-avatar__initials" aria-hidden="true">{initials}</span>
      {showImage && <img ref={imageRef} src={src} alt="" aria-hidden="true" loading="lazy" decoding="async" onError={() => setFailedSource(src!)} />}
    </span>
  );
}

import type { HTMLAttributes } from 'react';
import { cx } from '@/utils/cx';

export type BadgeColor = 'primary' | 'neutral' | 'new';
export type BadgeProps = Omit<HTMLAttributes<HTMLSpanElement>, 'color'> & { color?: BadgeColor; variant?: 'count' | 'label' | 'pill' | 'subtle' | 'index' };

export function Badge({ color = 'neutral', variant = 'count', className, ...props }: BadgeProps) {
  return <span data-color={color} data-variant={variant} className={cx('ui-badge', className)} {...props} />;
}

'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

import type { ButtonHTMLAttributes, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CloseButtonSize = '2xs' | 'xs' | 'sm' | 'md';

export type CloseButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'> & {
  size?: CloseButtonSize;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

const glyphSizes: Record<CloseButtonSize, number> = { '2xs': 8, xs: 11, sm: 13, md: 17 };
const strokes: Record<CloseButtonSize, number> = { '2xs': 1.6, xs: 2, sm: 2, md: 2.5 };

export function CloseButton({ size = 'xs', className, type = 'button', ...props }: CloseButtonProps) {
  const glyph = glyphSizes[size];
  const inset = size === '2xs' ? 1.4 : 2;
  return (
    <button type={type} data-size={size} className={cx('ui-close-button', className)} {...props}>
      <svg width={glyph} height={glyph} viewBox={`0 0 ${glyph} ${glyph}`} fill="none" aria-hidden="true">
        <path d={`M${inset} ${inset}L${glyph - inset} ${glyph - inset}M${glyph - inset} ${inset}L${inset} ${glyph - inset}`} stroke="currentColor" strokeWidth={strokes[size]} strokeLinecap="round" />
      </svg>
    </button>
  );
}

import type { HTMLAttributes } from 'react';
import { cx } from '@/utils/cx';

export type KbdProps = HTMLAttributes<HTMLElement> & {
  variant?: 'soft' | 'outline';
  size?: 'small' | 'medium';
};

export function Kbd({ className, variant = 'soft', size = 'small', ...props }: KbdProps) {
  return <kbd className={cx('ui-kbd', className)} data-variant={variant} data-size={size} {...props} />;
}

/** Supply an aria-label when the visible keys use platform-specific symbols. */
export function KbdGroup({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <kbd className={cx('ui-kbd-group', className)} {...props}/>;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { RiMoonLine, RiSunLine } from '@remixicon/react';
import { useAppearance } from '@/hooks/use-appearance';

export function ThemeSwitch({ className = '' }: { className?: string }) {
  const { theme, setTheme } = useAppearance();
  return <div className={`ui-theme-switch ${className}`} role="group" aria-label="Appearance">
    <button type="button" aria-label="Light appearance" aria-pressed={theme === 'light'} onClick={event => setTheme('light', event)}><RiSunLine size={17}/></button>
    <button type="button" aria-label="Dark appearance" aria-pressed={theme === 'dark'} onClick={event => setTheme('dark', event)}><RiMoonLine size={17}/></button>
  </div>;
}

'use client';

import { useEffect, useRef, useState, type Ref } from 'react';
import { RiLayoutLeftLine, RiSearchLine } from '@remixicon/react';
import { Announcement } from '@/components/base/announcement/announcement';
import { Avatar } from '@/components/base/avatar/avatar';
import { Badge } from '@/components/base/badges/badge';
import { Kbd } from '@/components/base/kbd/kbd';
import { ThemeSwitch } from '@/components/base/theme-switch/theme-switch';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export interface SidebarItem {
  key: string;
  label: string;
  icon: IconComponent;
  href?: string;
  badge?: string | number;
}

export interface SidebarIdentity { name: string; initials: string; image?: string; email?: string }
export type SidebarSelectionVariant = 'accent' | 'neutral';
export interface SidebarProps {
  ref?: Ref<HTMLElement>;
  role?: 'dialog';
  'aria-modal'?: boolean;
  workspace: SidebarIdentity;
  user: SidebarIdentity;
  items: SidebarItem[];
  secondaryItems?: SidebarItem[];
  selectedKey?: string;
  defaultSelectedKey?: string;
  selectionVariant?: SidebarSelectionVariant;
  onSelectionChange?: (key: string) => void;
  onWorkspaceClick?: () => void;
  onUserClick?: () => void;
  announcement?: { title: string; description: string; actionLabel?: string; onAction?: () => void };
  collapsed?: boolean;
  showThemeSwitch?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  className?: string;
  'aria-label'?: string;
}

export function Sidebar({ ref, role, 'aria-modal': ariaModal, workspace, user, items, secondaryItems = [], selectedKey, defaultSelectedKey, selectionVariant = 'accent', onSelectionChange, onWorkspaceClick, onUserClick, announcement, collapsed, showThemeSwitch = false, defaultCollapsed = false, onCollapsedChange, className, 'aria-label': ariaLabel = 'Workspace navigation' }: SidebarProps) {
  const [internalCollapsed, setInternalCollapsed] = useState(defaultCollapsed);
  const [internalSelected, setInternalSelected] = useState(defaultSelectedKey ?? items[0]?.key);
  const [query, setQuery] = useState('');
  const searchRef = useRef<HTMLInputElement>(null);
  const isCollapsed = collapsed === undefined ? internalCollapsed : collapsed;
  const selected = selectedKey === undefined ? internalSelected : selectedKey;
  const shownItems = items.filter(item => item.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  const shownSecondary = secondaryItems.filter(item => item.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));

  useEffect(() => {
    if (!isCollapsed && query) searchRef.current?.focus();
  }, [isCollapsed, query]);

  function setCollapsed(next: boolean) {
    if (next) setQuery('');
    if (collapsed === undefined) setInternalCollapsed(next);
    onCollapsedChange?.(next);
  }

  function select(key: string) {
    if (selectedKey === undefined) setInternalSelected(key);
    onSelectionChange?.(key);
  }

  function navItem(item: SidebarItem) {
    const Icon = item.icon;
    const isSelected = item.key === selected;
    const content = <><Icon className="ui-app-sidebar__nav-icon" aria-hidden /><span className="ui-app-sidebar__nav-label">{item.label}</span>{item.badge !== undefined && <Badge color={isSelected && selectionVariant === 'accent' ? 'primary' : 'neutral'} className="ui-app-sidebar__badge">{item.badge}</Badge>}</>;
    const shared = { className: 'ui-app-sidebar__nav-item', 'aria-label': item.label, 'aria-current': isSelected ? 'page' as const : undefined, title: isCollapsed ? item.label : undefined, onClick: () => select(item.key) };
    return item.href ? <a key={item.key} {...shared} href={item.href}>{content}</a> : <button key={item.key} {...shared} type="button">{content}</button>;
  }

  return <aside ref={ref} role={role} aria-modal={ariaModal} className={cx('ui-app-sidebar', className)} data-selection-variant={selectionVariant} data-collapsed={isCollapsed || undefined} aria-label={ariaLabel} onKeyDown={event => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); if (isCollapsed) setCollapsed(false); window.requestAnimationFrame(() => searchRef.current?.focus()); } }}>
    <div className="ui-app-sidebar__top">
      <div className="ui-app-sidebar__head">
        {onWorkspaceClick ? <button type="button" className="ui-app-sidebar__identity" aria-label={`Workspace: ${workspace.name}`} onClick={onWorkspaceClick}><Avatar size="md" initials={workspace.initials} src={workspace.image} alt={workspace.name} /><span>{workspace.name}</span></button> : <div className="ui-app-sidebar__identity"><Avatar size="md" initials={workspace.initials} src={workspace.image} alt={workspace.name} /><span>{workspace.name}</span></div>}
        <button type="button" className="ui-app-sidebar__collapse" aria-label={isCollapsed ? 'Expand sidebar' : 'Collapse sidebar'} aria-expanded={!isCollapsed} onClick={() => setCollapsed(!isCollapsed)}><RiLayoutLeftLine size={19} aria-hidden /></button>
      </div>
      <div className="ui-app-sidebar__search-wrap">
        <label className="ui-app-sidebar__search" aria-hidden={isCollapsed || undefined}><RiSearchLine size={18} aria-hidden /><input ref={searchRef} type="search" tabIndex={isCollapsed ? -1 : undefined} value={query} onChange={event => setQuery(event.target.value)} placeholder="Quick Search" aria-label="Search navigation" /><Kbd>⌘K</Kbd></label>
        <button type="button" className="ui-app-sidebar__search-rail" aria-label="Search navigation" tabIndex={isCollapsed ? undefined : -1} onClick={() => { setCollapsed(false); window.requestAnimationFrame(() => searchRef.current?.focus()); }}><RiSearchLine size={18} aria-hidden /></button>
      </div>
      <nav className="ui-app-sidebar__nav" aria-label="Primary navigation">{shownItems.map(navItem)}{shownItems.length === 0 && !isCollapsed && <span className="ui-app-sidebar__empty">No matching pages</span>}</nav>
    </div>
    <div className="ui-app-sidebar__bottom">
      {showThemeSwitch && <ThemeSwitch/>}
      {secondaryItems.length > 0 && <nav className="ui-app-sidebar__nav ui-app-sidebar__nav--secondary" aria-label="Secondary navigation">{shownSecondary.map(navItem)}</nav>}
      {announcement && <div className="ui-app-sidebar__announcement" aria-hidden={isCollapsed || undefined} inert={isCollapsed}><Announcement title={announcement.title} description={announcement.description} actionLabel={announcement.actionLabel} onAction={announcement.onAction} /></div>}
      {onUserClick ? <button type="button" className="ui-app-sidebar__user" aria-label={`Account: ${user.name}`} onClick={onUserClick}><Avatar size="sm" initials={user.initials} src={user.image} alt={user.name} /><span><strong>{user.name}</strong>{user.email && <small>{user.email}</small>}</span></button> : <div className="ui-app-sidebar__user"><Avatar size="sm" initials={user.initials} src={user.image} alt={user.name} /><span><strong>{user.name}</strong>{user.email && <small>{user.email}</small>}</span></div>}
    </div>
  </aside>;
}

import colors from './colors.json';

export type Accent = keyof typeof colors.accents;
export const accentNames = Object.keys(colors.accents) as Accent[];
export const accentPalettes = colors.accents;
export const accents = accentNames.map(id => ({ id, label: colors.accents[id].label, swatch: colors.accents[id].ramp['500'] }));

export function isAccent(value: string | null | undefined): value is Accent {
  return value != null && Object.hasOwn(colors.accents, value);
}

'use client';

import { useEffect, useState } from 'react';
import { transitionTheme, type ThemeChangeEvent } from '@/utils/theme-transition';
import { isAccent, type Accent } from '@/config/appearance';

export type Theme = 'light' | 'dark';
export type { Accent } from '@/config/appearance';

export function useAppearance() {
  const [theme, setThemeState] = useState<Theme>('light');
  const [accent, setAccentState] = useState<Accent>('blue');

  useEffect(() => {
    function syncAppearance() {
      setThemeState(document.documentElement.classList.contains('dark') ? 'dark' : 'light');
      const current = document.documentElement.dataset.accent;
      setAccentState(isAccent(current) ? current : 'blue');
    }
    syncAppearance();
    const observer = new MutationObserver(syncAppearance);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class', 'data-accent'] });
    return () => observer.disconnect();
  }, []);

  function setTheme(next: Theme, event?: ThemeChangeEvent) {
    if (document.documentElement.classList.contains('dark') === (next === 'dark')) return;
    void transitionTheme(() => {
      document.documentElement.classList.toggle('dark', next === 'dark');
      try { window.localStorage.setItem('appui:theme', next); } catch { /* Appearance also works without storage. */ }
      setThemeState(next);
    }, event);
  }

  function setAccent(next: Accent) {
    if (next === 'blue') delete document.documentElement.dataset.accent;
    else document.documentElement.dataset.accent = next;
    try { window.localStorage.setItem('appui:accent', next); } catch { /* Appearance also works without storage. */ }
    setAccentState(next);
  }

  return { theme, accent, setTheme, setAccent };
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});

'use client';

import type { MouseEvent } from 'react';
import { flushSync } from 'react-dom';

export type ThemeChangeEvent = Pick<MouseEvent<HTMLElement>, 'clientX' | 'clientY' | 'currentTarget'>;
let transitioning = false;

/** Reveal the new appearance from the pointer, or the control center for keyboards. */
export async function transitionTheme(update: () => void, event?: ThemeChangeEvent) {
  if (transitioning) return;
  if (!document.startViewTransition || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    update();
    return;
  }

  const bounds = event?.currentTarget.getBoundingClientRect();
  const pointer = event && (event.clientX !== 0 || event.clientY !== 0);
  const x = Math.max(0, Math.min(window.innerWidth, pointer ? event.clientX : bounds ? bounds.left + bounds.width / 2 : window.innerWidth / 2));
  const y = Math.max(0, Math.min(window.innerHeight, pointer ? event.clientY : bounds ? bounds.top + bounds.height / 2 : window.innerHeight / 2));
  const diameter = 2.5 * Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y));
  const root = document.documentElement;
  const mask = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><filter id="soft" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="2"/></filter></defs><circle cx="50" cy="50" r="42" fill="white" filter="url(#soft)"/></svg>';
  const properties = {
    '--theme-reveal-x': `${x}px`,
    '--theme-reveal-y': `${y}px`,
    '--theme-reveal-left': `${x - diameter / 2}px`,
    '--theme-reveal-top': `${y - diameter / 2}px`,
    '--theme-reveal-size': `${diameter}px`,
    '--theme-reveal-mask': `url("data:image/svg+xml,${encodeURIComponent(mask)}")`,
  };
  transitioning = true;
  Object.entries(properties).forEach(([key, value]) => root.style.setProperty(key, value));
  root.classList.add('ui-theme-transitioning');
  let committed = false;
  const commit = () => {
    if (committed) return;
    committed = true;
    flushSync(update);
  };
  try {
    const transition = document.startViewTransition(commit);
    await transition.ready;
    await transition.finished;
  } catch {
    // A hidden tab or interrupted snapshot still needs the requested appearance.
    commit();
  } finally {
    root.classList.remove('ui-theme-transitioning');
    Object.keys(properties).forEach(key => root.style.removeProperty(key));
    transitioning = false;
  }
}
